// Original satire adapted from the creator's private chronicles and verified quiz.
// Source answers, private identities and research records are deliberately omitted.
const c = (text, result, delta, flags = [], extra = {}) => ({ text, detail: '', result, delta, flags, ...extra });
const participants = {
  'sophie-elevator-silence': ['sophie', 'sonny'],
  'sophie-dessert-ownership': ['sophie', 'sonny'],
  'sophie-print-page-trace': ['sophie', 'sonny']
};
const scene = (speaker, slug, title, body, wing, replies, roles, sources = []) => {
  const offset = [...slug].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 3;
  return {
    id: `cast35-${slug}`, speaker, title, body, wing,
    era: '同事加場・誰都不只一張名片', minRules: 35, minTurn: 1, weight: 1.35,
    sourceIds: [...new Set(['characterFiction', ...sources])],
    ...(participants[slug] ? { participants: [...participants[slug]] } : {}),
    ...(roles?.length ? { roles } : {}),
    choices: [
      c(replies[0][0], replies[0][1], { skill: 5 + offset, trust: 5, energy: -6 - offset, mood: -2 }, ['evidence']),
      c(replies[1][0], replies[1][1], { lick: 5 + offset, trust: -5, energy: -6 - offset, mood: -5 }),
      c(replies[2][0], replies[2][1], { slack: 6 + offset, trust: 4, energy: -4 - offset, mood: 4 }, ['archive'], { wild: true })
    ]
  };
};

